/**
 * hermes-neon-h — Animated neon H mark for Hermes Desktop.
 * ASV Labs / Charles Bonetti. Opt-in disk plugin (defaultEnabled: false).
 *
 * Install: copy this folder to $HERMES_HOME/desktop-plugins/hermes-neon-h/
 * (default HERMES_HOME=~/.hermes), then ⌘K → Reload desktop plugins.
 *
 * Plain ESM, uncompiled. Only these imports resolve:
 *   @hermes/plugin-sdk, react, react/jsx-runtime
 *
 * Status polling is polite (~45–60s). User-Agent-ish note: browsers send a
 * normal fetch UA; we do not spoof. Prefer statuspage JSON with CORS *.
 */

import {
  host,
  haptic,
  Tip,
  cn,
  useValue,
  useQuery,
  Button,
  Input,
  Switch,
  SegmentedControl,
  StatusDot,
  ScrollArea,
  Separator,
  Badge,
  PALETTE_AREA,
  STATUSBAR_AREAS,
  PANES_AREA
} from '@hermes/plugin-sdk'
import { useEffect, useRef, useState, useCallback, useMemo } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

const ID = 'hermes-neon-h'
const POLL_MS = 50000 // polite: 45–60s window; midway default

/** Embedded logo (PNG). Tint via canvas compositing at draw time. */
const LOGO_DATA_URL = "data:image/png;base64,"

// ---------------------------------------------------------------------------
// Provider registry (extensible)
// ---------------------------------------------------------------------------

const DEFAULT_COLORS = {
  openai: '#10a37f',
  anthropic: '#d4a27f',
  google: '#4285f4',
  xai: '#ff6b2c',
  hermes: '#ff6b2c',
  warn: '#f59e0b',
  major: '#ef4444',
  unknown: '#94a3b8'
}

/**
 * Watched providers. `kind`:
 *   statuspage — Atlassian Statuspage /api/v2/summary.json
 *   gcp        — Google Cloud incidents.json (proxy for Gemini; see README)
 *   xai        — status.x.ai JSON first, HTML keyword sniff fallback
 */
const PROVIDER_DEFS = {
  openai: {
    id: 'openai',
    label: 'OpenAI',
    short: 'OAI',
    kind: 'statuspage',
    url: 'https://status.openai.com/api/v2/summary.json',
    hints: ['openai', 'gpt', 'o1', 'o3', 'o4', 'chatgpt']
  },
  anthropic: {
    id: 'anthropic',
    label: 'Anthropic',
    short: 'ANT',
    kind: 'statuspage',
    // anthropic status redirects here
    url: 'https://status.claude.com/api/v2/summary.json',
    hints: ['anthropic', 'claude', 'sonnet', 'opus', 'haiku']
  },
  google: {
    id: 'google',
    label: 'Google',
    short: 'GOOG',
    kind: 'gcp',
    url: 'https://status.cloud.google.com/incidents.json',
    hints: ['google', 'gemini', 'bard', 'vertex', 'palm']
  },
  xai: {
    id: 'xai',
    label: 'xAI',
    short: 'xAI',
    kind: 'xai',
    url: 'https://status.x.ai/api/v2/summary.json',
    htmlUrl: 'https://status.x.ai/',
    hints: ['xai', 'x.ai', 'grok']
  }
}

const ANIM_MODES = [
  { value: 'breathe', label: 'Breathe' },
  { value: 'static', label: 'Static' },
  { value: 'pulse-on-busy', label: 'Pulse on busy' },
  { value: 'outage-flash', label: 'Outage flash' }
]

const STORAGE_KEYS = {
  colors: 'colors',
  animMode: 'animMode',
  watched: 'watched',
  panePlacement: 'panePlacement'
}

const DEFAULT_WATCHED = ['openai', 'anthropic', 'google', 'xai']

// Module-scoped storage handle (set in register)
let _storage = null

// ---------------------------------------------------------------------------
// Status helpers
// ---------------------------------------------------------------------------

function mapStatuspageIndicator(indicator) {
  const v = String(indicator || '').toLowerCase()
  if (v === 'none' || v === 'operational') return 'operational'
  if (v === 'minor') return 'degraded'
  if (v === 'major' || v === 'critical') return 'major'
  return 'unknown'
}

async function fetchStatuspage(url) {
  const res = await fetch(url, { credentials: 'omit', cache: 'no-store' })
  if (!res.ok) throw new Error('HTTP ' + res.status)
  const data = await res.json()
  const indicator = data && data.status ? data.status.indicator : null
  return {
    status: mapStatuspageIndicator(indicator),
    description: (data && data.status && data.status.description) || indicator || '',
    source: 'statuspage'
  }
}

async function fetchGcpIncidents(url) {
  // Honest proxy: GCP public incidents, not a dedicated Gemini consumer page.
  const res = await fetch(url, { credentials: 'omit', cache: 'no-store' })
  if (!res.ok) throw new Error('HTTP ' + res.status)
  const incidents = await res.json()
  if (!Array.isArray(incidents) || incidents.length === 0) {
    return { status: 'operational', description: 'No open GCP incidents', source: 'gcp' }
  }
  const open = incidents.filter((inc) => {
    const s = String((inc && inc.status) || '').toLowerCase()
    return s && ['resolved', 'closed', 'end', 'ended'].indexOf(s) === -1
  })
  if (open.length === 0) {
    return { status: 'operational', description: 'No open GCP incidents', source: 'gcp' }
  }
  let worst = 'degraded'
  for (let i = 0; i < open.length; i++) {
    const inc = open[i]
    const sev = String((inc && (inc.severity || inc.highest_severity)) || '').toLowerCase()
    if (sev.indexOf('high') !== -1 || sev.indexOf('critical') !== -1 || sev === 'major') {
      worst = 'major'
      break
    }
  }
  return {
    status: worst,
    description: open.length + ' open GCP incident(s)',
    source: 'gcp'
  }
}

function sniffXaiHtml(html) {
  const text = String(html || '').toLowerCase()
  // Do not invent operational — only mark when keywords are clear.
  if (
    /all systems? (are )?operational/.test(text) ||
    /status[^a-z]{0,24}operational/.test(text) ||
    />\s*operational\s*</.test(text)
  ) {
    return { status: 'operational', description: 'HTML sniff: operational', source: 'xai-html' }
  }
  if (/major outage|critical|service disruption/.test(text)) {
    return { status: 'major', description: 'HTML sniff: major', source: 'xai-html' }
  }
  if (/degraded|partial outage|minor/.test(text)) {
    return { status: 'degraded', description: 'HTML sniff: degraded', source: 'xai-html' }
  }
  return { status: 'unknown', description: 'HTML sniff inconclusive', source: 'xai-html' }
}

async function fetchXai(def) {
  try {
    return await fetchStatuspage(def.url)
  } catch (_e) {
    // fall through to HTML
  }
  try {
    const res = await fetch(def.htmlUrl, { credentials: 'omit', cache: 'no-store' })
    if (!res.ok) throw new Error('HTTP ' + res.status)
    const html = await res.text()
    return sniffXaiHtml(html)
  } catch (e) {
    return {
      status: 'unknown',
      description: (e && e.message) || 'xAI status unreachable',
      source: 'xai-failed'
    }
  }
}

async function fetchProviderStatus(def) {
  try {
    if (def.kind === 'statuspage') return await fetchStatuspage(def.url)
    if (def.kind === 'gcp') return await fetchGcpIncidents(def.url)
    if (def.kind === 'xai') return await fetchXai(def)
    return { status: 'unknown', description: 'Unsupported kind', source: 'none' }
  } catch (e) {
    return {
      status: 'unknown',
      description: (e && e.message) || 'fetch failed',
      source: 'error'
    }
  }
}

async function fetchAllStatuses(watched) {
  const ids = watched && watched.length ? watched : DEFAULT_WATCHED
  const entries = await Promise.all(
    ids.map(async (id) => {
      const def = PROVIDER_DEFS[id]
      if (!def) {
        return [id, { status: 'unknown', description: 'unknown provider', source: 'none' }]
      }
      const result = await fetchProviderStatus(def)
      return [id, Object.assign({}, result, { id: id, label: def.label, short: def.short })]
    })
  )
  const out = {}
  for (let i = 0; i < entries.length; i++) {
    out[entries[i][0]] = entries[i][1]
  }
  return out
}

// ---------------------------------------------------------------------------
// Active provider parsing
// ---------------------------------------------------------------------------

function parseProviderHint(model, profile) {
  const blob = String(model || '') + ' ' + String(profile || '')
  const lower = blob.toLowerCase()
  const order = ['anthropic', 'openai', 'google', 'xai']
  for (let i = 0; i < order.length; i++) {
    const id = order[i]
    const hints = (PROVIDER_DEFS[id] && PROVIDER_DEFS[id].hints) || []
    for (let j = 0; j < hints.length; j++) {
      if (lower.indexOf(hints[j]) !== -1) return id
    }
  }
  return null
}

function loadSettings() {
  const storedColors = _storage ? _storage.get(STORAGE_KEYS.colors, null) : null
  const colors = Object.assign({}, DEFAULT_COLORS, storedColors || {})
  const animMode = (_storage && _storage.get(STORAGE_KEYS.animMode, 'breathe')) || 'breathe'
  const watched = (_storage && _storage.get(STORAGE_KEYS.watched, DEFAULT_WATCHED)) || DEFAULT_WATCHED
  const panePlacement =
    (_storage && _storage.get(STORAGE_KEYS.panePlacement, 'bottom')) || 'bottom'
  return { colors: colors, animMode: animMode, watched: watched, panePlacement: panePlacement }
}

function savePartial(key, value) {
  if (_storage) _storage.set(key, value)
}

// ---------------------------------------------------------------------------
// Color / visual mapping
// ---------------------------------------------------------------------------

function hexToRgb(hex) {
  const h = String(hex || '').replace('#', '')
  if (h.length !== 6) return { r: 255, g: 107, b: 44 }
  return {
    r: parseInt(h.slice(0, 2), 16),
    g: parseInt(h.slice(2, 4), 16),
    b: parseInt(h.slice(4, 6), 16)
  }
}

function statusColor(status, providerId, colors) {
  if (status === 'major') return colors.major || DEFAULT_COLORS.major
  if (status === 'degraded') return colors.warn || DEFAULT_COLORS.warn
  if (status === 'unknown') return colors.unknown || DEFAULT_COLORS.unknown
  return colors[providerId] || colors.hermes || DEFAULT_COLORS.xai
}

function pulseParams(status, animMode, busy) {
  let amp = 0.18
  let speed = 1.0
  let flash = false

  if (animMode === 'static') {
    amp = 0
    speed = 0
  } else if (animMode === 'pulse-on-busy') {
    amp = busy ? 0.35 : 0.06
    speed = busy ? 2.2 : 0.6
  } else if (animMode === 'outage-flash') {
    if (status === 'major') {
      amp = 0.55
      speed = 4.5
      flash = true
    } else if (status === 'degraded') {
      amp = 0.32
      speed = 2.4
    } else {
      amp = 0.14
      speed = 1.0
    }
  } else {
    // breathe (default)
    if (status === 'major') {
      amp = 0.5
      speed = 3.5
      flash = true
    } else if (status === 'degraded') {
      amp = 0.3
      speed = 2.0
    } else if (status === 'unknown') {
      amp = 0.12
      speed = 0.7
    } else {
      amp = 0.16
      speed = 1.0
    }
  }

  if (busy && animMode !== 'static') {
    amp = Math.min(0.7, amp * 1.55)
    speed *= 1.45
  }
  return { amp: amp, speed: speed, flash: flash }
}

// ---------------------------------------------------------------------------
// Canvas neon H
// ---------------------------------------------------------------------------

let _logoImg = null
let _logoFailed = false

function ensureLogo() {
  if (_logoImg || _logoFailed) return _logoImg
  const img = new Image()
  img.decoding = 'async'
  img.src = LOGO_DATA_URL
  img.onerror = function () {
    _logoFailed = true
  }
  _logoImg = img
  return img
}

function drawNeonH(ctx2d, w, h, opts) {
  const color = opts.color
  const amp = opts.amp
  const speed = opts.speed
  const flash = opts.flash
  const t = opts.t
  const busy = opts.busy
  const rgb = hexToRgb(color)
  const cx = w / 2
  const cy = h / 2
  const size = Math.min(w, h) * 0.72

  const phase = speed > 0 ? (Math.sin(t * speed * 2.2) + 1) / 2 : 0.5
  let breath = 1 - amp + amp * phase
  if (flash) {
    const f = (Math.sin(t * speed * 8) + 1) / 2
    breath = 0.35 + 0.65 * f
  }
  if (busy) breath = Math.min(1.15, breath * 1.08)

  ctx2d.clearRect(0, 0, w, h)
  ctx2d.fillStyle = '#000000'
  ctx2d.fillRect(0, 0, w, h)

  const glowR = size * (0.55 + 0.15 * breath)
  const g = ctx2d.createRadialGradient(cx, cy, size * 0.08, cx, cy, glowR)
  g.addColorStop(0, 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + 0.35 * breath + ')')
  g.addColorStop(0.45, 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + 0.12 * breath + ')')
  g.addColorStop(1, 'rgba(0,0,0,0)')
  ctx2d.fillStyle = g
  ctx2d.fillRect(0, 0, w, h)

  const img = ensureLogo()
  const ready = img && img.complete && img.naturalWidth > 0

  if (ready) {
    const iw = img.naturalWidth
    const ih = img.naturalHeight
    const scale = (size / Math.max(iw, ih)) * (0.92 + 0.04 * breath)
    const dw = iw * scale
    const dh = ih * scale
    const dx = cx - dw / 2
    const dy = cy - dh / 2

    ctx2d.save()
    ctx2d.globalAlpha = 0.85 + 0.15 * breath
    ctx2d.drawImage(img, dx, dy, dw, dh)
    ctx2d.restore()

    ctx2d.save()
    ctx2d.globalCompositeOperation = 'source-atop'
    ctx2d.globalAlpha = 0.55 + 0.25 * breath
    ctx2d.fillStyle = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',1)'
    ctx2d.fillRect(dx, dy, dw, dh)
    ctx2d.restore()

    ctx2d.save()
    ctx2d.globalCompositeOperation = 'lighter'
    ctx2d.globalAlpha = 0.18 * breath
    ctx2d.shadowColor = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',0.9)'
    ctx2d.shadowBlur = 28 + 40 * amp * breath
    ctx2d.drawImage(img, dx, dy, dw, dh)
    ctx2d.restore()
  } else {
    ctx2d.save()
    ctx2d.translate(cx, cy)
    const barW = size * 0.16
    const barH = size * 0.72
    const gap = size * 0.28
    ctx2d.shadowColor = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + 0.9 * breath + ')'
    ctx2d.shadowBlur = 24 + 36 * amp * breath
    ctx2d.fillStyle = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + (0.85 + 0.15 * breath) + ')'
    ctx2d.fillRect(-gap / 2 - barW, -barH / 2, barW, barH)
    ctx2d.fillRect(gap / 2, -barH / 2, barW, barH)
    ctx2d.fillRect(-gap / 2 - barW, -barW / 2, gap + 2 * barW, barW)
    ctx2d.restore()
  }

  if (busy) {
    ctx2d.save()
    ctx2d.strokeStyle =
      'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + (0.45 + 0.35 * phase) + ')'
    ctx2d.lineWidth = 2
    ctx2d.beginPath()
    ctx2d.arc(cx, cy, size * 0.48, t * 3, t * 3 + Math.PI * 1.2)
    ctx2d.stroke()
    ctx2d.restore()
  }
}

function NeonCanvas(props) {
  const color = props.color
  const status = props.status
  const animMode = props.animMode
  const busy = props.busy
  const wrapRef = useRef(null)
  const canvasRef = useRef(null)
  const rafRef = useRef(0)
  const startRef = useRef(0)

  useEffect(function () {
    ensureLogo()
  }, [])

  useEffect(
    function () {
      const wrap = wrapRef.current
      const canvas = canvasRef.current
      if (!wrap || !canvas) return undefined

      const resize = function () {
        const rect = wrap.getBoundingClientRect()
        const dpr = Math.min(window.devicePixelRatio || 1, 2)
        const cssW = Math.max(1, Math.floor(rect.width))
        const cssH = Math.max(1, Math.floor(rect.height))
        canvas.width = Math.floor(cssW * dpr)
        canvas.height = Math.floor(cssH * dpr)
        canvas.style.width = cssW + 'px'
        canvas.style.height = cssH + 'px'
        const c = canvas.getContext('2d')
        if (c) c.setTransform(dpr, 0, 0, dpr, 0, 0)
      }

      resize()
      const ro = new ResizeObserver(function () {
        resize()
      })
      ro.observe(wrap)

      startRef.current = performance.now()
      const tick = function (now) {
        const c = canvas.getContext('2d')
        if (c) {
          const t = (now - startRef.current) / 1000
          const pulse = pulseParams(status, animMode, busy)
          const cssW = canvas.clientWidth || 1
          const cssH = canvas.clientHeight || 1
          drawNeonH(c, cssW, cssH, {
            color: color,
            amp: pulse.amp,
            speed: pulse.speed,
            flash: pulse.flash,
            t: t,
            busy: busy
          })
        }
        rafRef.current = requestAnimationFrame(tick)
      }
      rafRef.current = requestAnimationFrame(tick)

      return function () {
        cancelAnimationFrame(rafRef.current)
        ro.disconnect()
      }
    },
    [color, status, animMode, busy]
  )

  return jsx('div', {
    ref: wrapRef,
    className: 'h-full w-full min-h-[120px] bg-black',
    children: jsx('canvas', {
      ref: canvasRef,
      className: 'block h-full w-full',
      'aria-label': 'Neon H provider health mark'
    })
  })
}

// ---------------------------------------------------------------------------
// Hooks
// ---------------------------------------------------------------------------

function useProviderStatuses(watched) {
  const key = watched.slice().sort().join(',')
  return useQuery({
    queryKey: [ID, 'provider-status', key],
    queryFn: function () {
      return fetchAllStatuses(watched)
    },
    refetchInterval: POLL_MS,
    staleTime: POLL_MS / 2,
    retry: 1,
    refetchOnWindowFocus: true
  })
}

function usePluginSettings() {
  const [settings, setSettings] = useState(function () {
    return loadSettings()
  })

  const update = useCallback(function (patch) {
    setSettings(function (prev) {
      const next = Object.assign({}, prev, patch)
      if (patch.colors) {
        next.colors = Object.assign({}, prev.colors, patch.colors)
        savePartial(STORAGE_KEYS.colors, next.colors)
      }
      if (patch.animMode != null) savePartial(STORAGE_KEYS.animMode, next.animMode)
      if (patch.watched) savePartial(STORAGE_KEYS.watched, next.watched)
      if (patch.panePlacement != null) savePartial(STORAGE_KEYS.panePlacement, next.panePlacement)
      return next
    })
  }, [])

  const resetColors = useCallback(function () {
    const colors = Object.assign({}, DEFAULT_COLORS)
    savePartial(STORAGE_KEYS.colors, colors)
    setSettings(function (prev) {
      return Object.assign({}, prev, { colors: colors })
    })
  }, [])

  return { settings: settings, update: update, resetColors: resetColors }
}

// ---------------------------------------------------------------------------
// Mark pane
// ---------------------------------------------------------------------------

function MarkPane() {
  const model = useValue(host.state.model)
  const profile = useValue(host.state.profile)
  const busy = useValue(host.state.busy)
  const hook = usePluginSettings()
  const settings = hook.settings
  const query = useProviderStatuses(settings.watched)

  const activeId = useMemo(
    function () {
      return parseProviderHint(model, profile) || settings.watched[0] || 'xai'
    },
    [model, profile, settings.watched]
  )

  const activeStatus =
    (query.data && query.data[activeId] && query.data[activeId].status) || 'unknown'
  const color = statusColor(activeStatus, activeId, settings.colors)

  const label = (PROVIDER_DEFS[activeId] && PROVIDER_DEFS[activeId].label) || activeId
  const st =
    (query.data && query.data[activeId] && query.data[activeId].status) ||
    (query.isLoading ? 'loading' : 'unknown')
  const subtitle = label + ' · ' + st + (busy ? ' · busy' : '')

  return jsxs('div', {
    className: 'flex h-full flex-col bg-black',
    children: [
      jsxs('div', {
        className:
          'flex items-center justify-between gap-2 border-b border-(--ui-stroke-secondary) px-2 py-1 text-[0.65rem] text-(--ui-text-tertiary)',
        children: [
          jsx('span', { className: 'truncate', children: subtitle }),
          jsx(Badge, {
            variant: 'secondary',
            className: 'shrink-0 text-[0.6rem]',
            children: settings.animMode
          })
        ]
      }),
      jsx('div', {
        className: 'min-h-0 flex-1',
        children: jsx(NeonCanvas, {
          color: color,
          status: activeStatus,
          animMode: settings.animMode,
          busy: !!busy
        })
      })
    ]
  })
}

// ---------------------------------------------------------------------------
// Settings pane
// ---------------------------------------------------------------------------

function SettingsPane() {
  const hook = usePluginSettings()
  const settings = hook.settings
  const update = hook.update
  const resetColors = hook.resetColors

  const modeOptions = ANIM_MODES.map(function (m) {
    return { value: m.value, label: m.label }
  })

  const colorKeys = ['openai', 'anthropic', 'google', 'xai', 'warn', 'major']
  const colorFields = colorKeys.map(function (key) {
    return jsxs('div', {
      key: key,
      className: 'flex items-center gap-2',
      children: [
        jsx('div', {
          className: 'h-3 w-3 shrink-0 rounded-full border border-(--ui-stroke-secondary)',
          style: { backgroundColor: settings.colors[key] || DEFAULT_COLORS[key] }
        }),
        jsx('label', {
          className: 'w-20 shrink-0 text-xs text-(--ui-text-secondary)',
          children: key
        }),
        jsx(Input, {
          className: 'h-7 font-mono text-xs',
          value: settings.colors[key] || '',
          placeholder: DEFAULT_COLORS[key],
          onChange: function (e) {
            const patch = {}
            patch[key] = e.target.value
            update({ colors: patch })
          }
        })
      ]
    })
  })

  const watchToggles = DEFAULT_WATCHED.map(function (id) {
    const on = settings.watched.indexOf(id) !== -1
    return jsxs('div', {
      key: id,
      className: 'flex items-center justify-between gap-2 py-1',
      children: [
        jsx('span', {
          className: 'text-xs text-(--ui-text-secondary)',
          children: PROVIDER_DEFS[id].label
        }),
        jsx(Switch, {
          checked: on,
          onCheckedChange: function (checked) {
            let next
            if (checked) {
              next = Array.from(new Set(settings.watched.concat([id])))
            } else {
              next = settings.watched.filter(function (x) {
                return x !== id
              })
            }
            update({ watched: next.length ? next : [id] })
          }
        })
      ]
    })
  })

  const placementButtons = ['bottom', 'right'].map(function (p) {
    return jsx(Button, {
      key: p,
      size: 'sm',
      variant: settings.panePlacement === p ? 'default' : 'outline',
      onClick: function () {
        update({ panePlacement: p })
        host.notify({
          kind: 'info',
          message: 'Placement saved as ' + p + '. Reload plugins or re-open pane to apply.'
        })
      },
      children: p
    })
  })

  let animControl
  if (typeof SegmentedControl === 'function') {
    animControl = jsx(SegmentedControl, {
      value: settings.animMode,
      onValueChange: function (v) {
        update({ animMode: v })
      },
      options: modeOptions,
      items: modeOptions
    })
  } else {
    animControl = jsx('select', {
      className: 'rounded-md border border-(--ui-stroke-secondary) bg-transparent px-2 py-1 text-xs',
      value: settings.animMode,
      onChange: function (e) {
        update({ animMode: e.target.value })
      },
      children: ANIM_MODES.map(function (m) {
        return jsx('option', { value: m.value, children: m.label, key: m.value })
      })
    })
  }

  return jsx(ScrollArea, {
    className: 'h-full',
    children: jsxs('div', {
      className: 'flex flex-col gap-4 p-3 text-sm',
      children: [
        jsxs('div', {
          children: [
            jsx('div', {
              className: 'font-medium text-(--ui-text-primary)',
              children: 'Neon H settings'
            }),
            jsx('p', {
              className: 'mt-1 text-xs text-(--ui-text-tertiary)',
              children:
                'Provider-tinted neon mark. Canvas colors are intentional product accents; chrome uses theme vars.'
            })
          ]
        }),
        jsx(Separator, {}),
        jsxs('div', {
          className: 'flex flex-col gap-2',
          children: [
            jsx('div', {
              className: 'text-xs font-semibold uppercase tracking-wider text-(--ui-text-tertiary)',
              children: 'Animation'
            }),
            animControl
          ]
        }),
        jsxs('div', {
          className: 'flex flex-col gap-2',
          children: [
            jsx('div', {
              className: 'text-xs font-semibold uppercase tracking-wider text-(--ui-text-tertiary)',
              children: 'Pane placement'
            }),
            jsxs('div', { className: 'flex gap-2', children: placementButtons })
          ]
        }),
        jsx(Separator, {}),
        jsxs('div', {
          className: 'flex flex-col gap-2',
          children: [
            jsx('div', {
              className: 'text-xs font-semibold uppercase tracking-wider text-(--ui-text-tertiary)',
              children: 'Watched providers'
            }),
            jsx('div', { children: watchToggles })
          ]
        }),
        jsx(Separator, {}),
        jsxs('div', {
          className: 'flex flex-col gap-2',
          children: [
            jsxs('div', {
              className: 'flex items-center justify-between',
              children: [
                jsx('div', {
                  className:
                    'text-xs font-semibold uppercase tracking-wider text-(--ui-text-tertiary)',
                  children: 'Colors (hex)'
                }),
                jsx(Button, {
                  size: 'sm',
                  variant: 'ghost',
                  onClick: function () {
                    resetColors()
                    haptic('tap')
                  },
                  children: 'Reset'
                })
              ]
            }),
            jsx('div', { className: 'flex flex-col gap-2', children: colorFields })
          ]
        }),
        jsx(Separator, {}),
        jsx('p', {
          className: 'text-[0.65rem] text-(--ui-text-quaternary)',
          children:
            'Google uses GCP incidents.json (not a Gemini-only status page). xAI may report unknown if CORS/HTML sniff fails. Poll every ~50s.'
        })
      ]
    })
  })
}

// ---------------------------------------------------------------------------
// Status bar chips
// ---------------------------------------------------------------------------

function ProviderChip(props) {
  const providerId = props.providerId
  const model = useValue(host.state.model)
  const profile = useValue(host.state.profile)
  const hook = usePluginSettings()
  const settings = hook.settings
  const query = useProviderStatuses(settings.watched)

  if (settings.watched.indexOf(providerId) === -1) return null

  const def = PROVIDER_DEFS[providerId]
  const row = query.data && query.data[providerId]
  const status = (row && row.status) || 'unknown'
  const active = parseProviderHint(model, profile) === providerId
  const color = statusColor(status, providerId, settings.colors)
  const tip =
    def.label +
    ': ' +
    status +
    (row && row.description ? ' — ' + row.description : '')

  let dot
  if (typeof StatusDot === 'function') {
    const mapped =
      status === 'operational'
        ? 'ok'
        : status === 'degraded'
          ? 'warn'
          : status === 'major'
            ? 'error'
            : 'unknown'
    dot = jsx(StatusDot, { status: mapped, style: { color: color } })
  } else {
    dot = jsx('span', {
      className: 'inline-block h-1.5 w-1.5 rounded-full',
      style: { backgroundColor: color }
    })
  }

  return jsx(Tip, {
    label: tip,
    children: jsxs('button', {
      type: 'button',
      className: cn(
        'inline-flex h-full items-center gap-1 px-1.5 text-[0.6875rem] transition-colors',
        'text-(--ui-text-tertiary) hover:bg-(--chrome-action-hover) hover:text-foreground',
        active ? 'text-foreground' : ''
      ),
      onClick: function () {
        haptic('tap')
        openNeonH()
      },
      children: [
        dot,
        jsx('span', {
          style: active ? { color: color } : undefined,
          children: def.short
        })
      ]
    })
  })
}

// ---------------------------------------------------------------------------
// Open helpers (workspace tab OR pane fallback)
// ---------------------------------------------------------------------------

function openNeonH() {
  if (typeof host.openWorkspace === 'function') {
    try {
      host.openWorkspace('hermes-neon-h:mark', {
        title: 'Neon H',
        minWidth: 280,
        render: function () {
          return jsx(MarkPane, {})
        }
      })
      return
    } catch (_e) {
      // fall through
    }
  }
  host.notify({
    kind: 'info',
    message:
      'Neon H pane is registered — open it from the layout / pane tabs (workspace API unavailable).'
  })
}

function openNeonSettings() {
  if (typeof host.openWorkspace === 'function') {
    try {
      host.openWorkspace('hermes-neon-h:settings', {
        title: 'Neon H settings',
        minWidth: 320,
        render: function () {
          return jsx(SettingsPane, {})
        }
      })
      return
    } catch (_e) {}
  }
  host.notify({
    kind: 'info',
    message: 'Neon H settings pane is registered — open it from the layout / pane tabs.'
  })
}

// ---------------------------------------------------------------------------
// Plugin export
// ---------------------------------------------------------------------------

export default {
  id: ID,
  name: 'Neon H',
  defaultEnabled: false,
  register: function (ctx) {
    _storage = ctx.storage
    const initial = loadSettings()
    const placement = initial.panePlacement === 'right' ? 'right' : 'bottom'
    const paneData =
      placement === 'bottom'
        ? {
            placement: 'bottom',
            dock: { pane: 'workspace', pos: 'bottom' },
            height: '200px'
          }
        : { placement: 'right', width: '260px' }

    ctx.register({
      id: 'mark',
      area: PANES_AREA,
      title: 'Neon H',
      data: paneData,
      render: function () {
        return jsx(MarkPane, {})
      }
    })

    ctx.register({
      id: 'settings',
      area: PANES_AREA,
      title: 'Neon H settings',
      data: { placement: 'right', width: '300px' },
      render: function () {
        return jsx(SettingsPane, {})
      }
    })

    const chipOrder = { openai: 140, anthropic: 141, google: 142, xai: 143 }
    for (let i = 0; i < DEFAULT_WATCHED.length; i++) {
      const id = DEFAULT_WATCHED[i]
      ctx.register({
        id: 'chip-' + id,
        area: STATUSBAR_AREAS.right,
        order: chipOrder[id] || 140,
        render: function () {
          return jsx(ProviderChip, { providerId: id })
        }
      })
    }

    ctx.register({
      id: 'palette-open',
      area: PALETTE_AREA,
      data: {
        id: 'hermes-neon-h.open',
        label: 'Open Neon H',
        keywords: ['neon', 'hermes', 'provider', 'status', 'logo'],
        run: function () {
          openNeonH()
        }
      }
    })

    ctx.register({
      id: 'palette-settings',
      area: PALETTE_AREA,
      data: {
        id: 'hermes-neon-h.settings',
        label: 'Open Neon H settings',
        keywords: ['neon', 'settings', 'colors', 'animation'],
        run: function () {
          openNeonSettings()
        }
      }
    })
  }
}
